mod tests {
    use super::*;
    use std::thread;

    #[test]
    fn same_player_transfer_returns() {
        let board = Board::new();
        board.join(1, 10);
        board.transfer(1, 1, 5);
        assert_eq!((board.score(1), board.total()), (10, 10));
    }

    #[test]
    fn concurrent_awards_are_not_lost() {
        let board = Board::new();
        board.join(1, 0);
        let handles: Vec<_> = (0..8)
            .map(|_| {
                let board = board.clone();
                thread::spawn(move || {
                    for _ in 0..10_000 {
                        board.award(1, 1);
                    }
                })
            })
            .collect();
        for handle in handles {
            handle.join().unwrap();
        }
        assert_eq!((board.score(1), board.total()), (80_000, 80_000));
    }

    #[test]
    fn opposite_transfers_do_not_deadlock() {
        let board = Board::new();
        board.join(1, 1_000_000);
        board.join(2, 1_000_000);
